/**
 * /changelog/ —— 变更记录页
 *
 * 🔴 **只写能落到已上线事实的条目**。每条要么对应一次真实上线（如退订抑制 2026-10-11
 *    上生产），要么对应一次对外可见的结构变更（如主站改为英文单语、产品线改名）。
 *    **不得**把计划中的事情写进这里 —— 那是 ROADMAP，写成已发布就是假状态。
 *
 * 🔴 **对外产物纪律**：不写内部仓名、内部路径、退役域名的具体字符串、内部系统名。
 *    （「改用单一主机名」可以写；那个被撤掉的主机名本身不写。）
 *
 * @author 恒哥
 * @since 2026-10-13
 */
import React from 'react';
import Layout from '../components/Layout';
import SEO from '../components/SEO';
import '../styles/marketing.css';
import T from '../i18n/LocalizedText';
import { usePageI18n } from '../i18n';

const RELEASES = [
  {
    date: '2026-11-01',
    title: 'Product line renamed to Whaleal Platform',
    items: [
      'The reach product, previously shown as Whaleal Messaging, is now Whaleal Platform.',
      'Whaleal Cart recovery email offers Friendly, Professional, and Urgency, with a follow-up wording for each.',
      'Public addresses that used /messaging/ redirect to /platform/.',
    ],
  },
  {
    date: '2026-10-13',
    title: 'Help center and new documentation sections',
    items: [
      'Help center expanded to a fuller set of articles covering connections, sending, statuses, limits, logs and troubleshooting.',
      'Added four browsable sections: Industries, Features, Use cases and Compare.',
      'Added a service status page covering the components of the platform and how an incident is handled.',
      'Added an HTML site map listing every page on the site in one place.',
    ],
  },
  {
    date: '2026-10-12',
    title: 'Product line renamed to Whaleal Messaging',
    items: [
      'The messaging product line, previously known as Whaleal SMS, is now Whaleal Messaging.',
      'The graphical console and the public pages moved onto a single hostname instead of two.',
      'The marketing site became English-only; older language-prefixed addresses redirect permanently to their English equivalents.',
      'The domain layout for the platform was consolidated from six hostnames to four — app, its API counterpart, the public API and the webhook endpoint.',
    ],
  },
  {
    date: '2026-10-11',
    title: 'Opt-out suppression for promotional SMS',
    items: [
      'Opt-out keywords are now honoured and applied to promotional traffic.',
      'Transactional messages — verification codes, delivery notices — are deliberately not affected, so a marketing opt-out does not silence a code someone needs.',
      'Suppression applies to the SMS channel.',
    ],
  },
];

export default function ChangelogPage(pageContext) {
  const { locale } = usePageI18n(pageContext);

  return (
    <Layout locale={pageContext?.locale}>
      <SEO
        title="Changelog — what shipped, and when"
        description="Dated release notes for Whaleal Platform: what changed, and which channel each change applies to."
        pathname="/changelog/"
        softwareApp={false} hrefLang={locale}
      />
      <div className="mk">
        <header className="mk-hero">
          <span className="mk-eyebrow"><T id="changelog.001">Changelog</T></span>
          <h1><T id="changelog.002">What shipped, and when</T></h1>
          <p className="mk-lead"><T id="changelog.003">
            Every entry here corresponds to something already live, so this page reads as a record
            of what you can rely on today — and of what changed the last time you looked.
          </T></p>
        </header>

        {RELEASES.map((r) => (
          <section className="mk-section" key={r.date}>
            <h2>
              {r.date} — {r.title}
            </h2>
            <ul className="mk-list">
              {r.items.map((it) => (
                <li key={it}>{it}</li>
              ))}
            </ul>
          </section>
        ))}

        <div className="mk-scope">
          <T id="changelog.004"><strong>Scope.</strong> Entries describe changes to Whaleal Platform and this website,
          and name the channel where a change applies to one channel only.
        </T></div>
      </div>
    </Layout>
  );
}
